cd /workspace/repo && cat > src/stock.mjs <<'EOF'
export class Stock {
  constructor(levels) {
    this.levels = levels.map((level) => ({ ...level, held: level.held ?? 0 }));
  }

  level(sku, warehouse) {
    return this.levels.find((level) => level.sku === sku && level.warehouse === warehouse);
  }

  forSku(sku) {
    return this.levels.filter((level) => level.sku === sku);
  }
}
EOF
cat > src/allocation.mjs <<'EOF'
export function allocate(levels, quantity) {
  const ordered = [...levels].sort(
    (a, b) =>
      a.priority - b.priority ||
      (a.warehouse < b.warehouse ? -1 : a.warehouse > b.warehouse ? 1 : 0),
  );
  let remaining = quantity;
  const lines = [];
  for (const level of ordered) {
    if (remaining === 0) break;
    const available = Math.max(0, level.onHand - (level.held ?? 0));
    const take = Math.min(available, remaining);
    if (take > 0) {
      lines.push({ warehouse: level.warehouse, quantity: take });
      remaining -= take;
    }
  }
  return { lines, backorderQuantity: remaining };
}
EOF
cat > src/audit.mjs <<'EOF'
export class AuditLog {
  constructor() {
    this.log = [];
  }

  record(entry) {
    this.log.push(structuredClone(entry));
  }

  entries() {
    return structuredClone(this.log);
  }
}
EOF
cat > src/api.mjs <<'EOF'
const CLIENT_ERRORS = { invalid_request: 400, invalid_quantity: 400, insufficient_stock: 409 };

export function handleReserve(book, body) {
  try {
    return { status: 201, body: book.reserve(body) };
  } catch (error) {
    const message = error instanceof Error ? error.message : undefined;
    return typeof message === 'string' && Object.hasOwn(CLIENT_ERRORS, message)
      ? { status: CLIENT_ERRORS[message], body: { error: message } }
      : { status: 500, body: { error: 'internal' } };
  }
}
EOF
